using System.Threading.Tasks;using System.Windows.Threading;using System;using System.IO;using System.Linq;using System.Reflection;using System.Threading;using System.Windows;using System.Windows.Controls;using System.Windows.Media;using System.Windows.Media.Imaging;
class WizardCheck {
 static int checks;static object Field(object owner,string name){return owner.GetType().GetField(name,BindingFlags.NonPublic|BindingFlags.Instance).GetValue(owner);}static void Check(bool value,string label){if(!value)throw new Exception(label);checks++;File.AppendAllText("wizard-check.log","PASS "+label+Environment.NewLine);}
 static void PumpUntil(Func<bool> ready){var until=DateTime.UtcNow.AddSeconds(40);while(!ready()){if(DateTime.UtcNow>until)throw new Exception("Installer UI operation timed out");var frame=new DispatcherFrame();Dispatcher.CurrentDispatcher.BeginInvoke(DispatcherPriority.Background,new Action(()=>frame.Continue=false));Dispatcher.PushFrame(frame);Thread.Sleep(3);}}static void Shot(SetupWizard wizard,string file){var root=(FrameworkElement)wizard.Content;root.Measure(new Size(860,710));root.Arrange(new Rect(0,0,860,710));root.UpdateLayout();var bmp=new RenderTargetBitmap(860,710,96,96,PixelFormats.Pbgra32);bmp.Render(root);var png=new PngBitmapEncoder();png.Frames.Add(BitmapFrame.Create(bmp));using(var stream=File.Create(file))png.Save(stream);}
 [STAThread]static int Main(){try{File.WriteAllText("wizard-check.log","");var app=new Application();SynchronizationContext.SetSynchronizationContext(new DispatcherSynchronizationContext());string target=Path.GetFullPath("wizard-selected-path/TV 助手");var wizard=new SetupWizard(target,false);wizard.Show();wizard.UpdateLayout();Check((int)Field(wizard,"page")==0,"installer starts on welcome page");Shot(wizard,"installer-welcome.png");((Button)Field(wizard,"next")).RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Check((int)Field(wizard,"page")==1,"installer displays installation directory page");var box=(TextBox)Field(wizard,"targetBox");Check(!box.IsReadOnly,"installation path is editable");box.Text=target;((CheckBox)Field(wizard,"desktop")).IsChecked=false;((CheckBox)Field(wizard,"startMenu")).IsChecked=false;Shot(wizard,"installer-path.png");((Button)Field(wizard,"next")).RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Check((int)Field(wizard,"page")==2,"installer displays review before writing files");var options=(InstallOptions)Field(wizard,"options");Check(Setup.Same(options.Target,target)&&!options.Desktop,"custom directory and shortcut choices reach review");Check(!Directory.Exists(target),"welcome and review do not install files");Shot(wizard,"installer-review.png");((Button)Field(wizard,"back")).RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Check((int)Field(wizard,"page")==1&&Setup.Same(((TextBox)Field(wizard,"targetBox")).Text,target),"back navigation preserves installation path");options.Register=false;options.Previous="";((Button)Field(wizard,"next")).RaiseEvent(new RoutedEventArgs(Button.ClickEvent));((Button)Field(wizard,"next")).RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Check((int)Field(wizard,"page")==3,"installer enters visible progress stage after confirmation");bool progressCaptured=false;((ProgressBar)Field(wizard,"progress")).ValueChanged+=(sender,eventArgs)=>{if(!progressCaptured&&eventArgs.NewValue>=20&&eventArgs.NewValue<=80){Shot(wizard,"installer-progress.png");progressCaptured=true;}};PumpUntil(()=>(int)Field(wizard,"page")==4||(int)Field(wizard,"page")==1);Check((int)Field(wizard,"page")==4&&File.Exists(Path.Combine(target,"TVStudio.exe")),"installer reaches completion after actual file extraction: "+((TextBlock)Field(wizard,"error")).Text);((CheckBox)Field(wizard,"launch")).IsChecked=false;Shot(wizard,"installer-finish.png");Check(wizard.IsVisible&&((Button)Field(wizard,"next")).Content.ToString()=="完成","completion waits for explicit finish click");((Button)Field(wizard,"next")).RaiseEvent(new RoutedEventArgs(Button.ClickEvent));app.Shutdown();File.AppendAllText("wizard-check.log",checks+" installer UI checks passed; installed only to test folder, no registry or shortcuts modified\n");return 0;}catch(Exception ex){File.AppendAllText("wizard-check.log",ex.ToString());return 1;}}
}


